-- Rollback for the TSR -> chat handoff change on local PID 283 (2026-10-05 17:58). Restores the survey queue,
-- alert 17, Close's branching, session-fallback-instrument, the randomization flag and the (empty) allocation table.
-- Apply: docker exec -i redcap_2023_1_db mysql -uredcap -predcap123 redcap < this-file
DELETE FROM redcap_surveys_queue WHERE survey_id IN (1619,1610,1617,1621,1616,1628,1613,1631,1615,1618,1622,1627,1624,1614,1625,1609,1611,1612,1620,1630,1629,1626,1623);
UPDATE redcap_alerts SET form_name='close', email_deleted=1, alert_condition='([event-name]=\'day_1_ed_arm_1\' or [event-name]=\'day_1_ed_arm_2\' or [event-name]=\'day_1_ed_arm_3\') and [close_complete]=\'2\' and [baseline1_complete]=\'2\'' WHERE alert_id=5965;
UPDATE redcap_metadata SET branching_logic='[event-name]=\'month_12_arm_1\'' WHERE project_id=283 AND field_name='desc_12m_end';
UPDATE redcap_metadata SET branching_logic='[event-name]=\'month_3_arm_1\'' WHERE project_id=283 AND field_name='desc_3m_end';
UPDATE redcap_metadata SET branching_logic='[event-name]=\'month_6_arm_1\'' WHERE project_id=283 AND field_name='desc_6m_end';
UPDATE redcap_metadata SET branching_logic='[event-name]=\'baseline_arm_1\'' WHERE project_id=283 AND field_name='desc_baseline_end';
UPDATE redcap_external_module_settings SET value='tsr' WHERE project_id=283 AND `key`='session-fallback-instrument' AND external_module_id=93;
UPDATE redcap_projects SET randomization=0 WHERE project_id=283;
DELETE FROM redcap_randomization_allocation WHERE rid=17;
